        capacity = newCapacity;
        configured = true;
        closed = false;
        bufferedWeight = 0;
        buffer.clear();
        committed.clear();
    }

    public static void add(Command command) {
        requireOpen();
        validate(command);
        buffer.add(command);
        bufferedWeight += command.getWeight();
        if (bufferedWeight > (capacity + 1) / 2) {
            commitBuffer();
        }
    }

    public static void addAll(List<Command> commands) {
        requireOpen();
        if (commands == null) {
            throw new IllegalArgumentException("Commands required");
