import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        check(Solution.committed().isEmpty(), "committed available before configuration");
        expect(IllegalStateException.class, () -> Solution.add(new Solution.Command("x", 1)));
        expect(IllegalStateException.class, () -> Solution.addAll(new ArrayList<Solution.Command>()));
        expect(IllegalStateException.class, () -> Solution.flush());
        expect(IllegalStateException.class, () -> Solution.close());
        expect(IllegalArgumentException.class, () -> Solution.configure(0, 1));
        expect(IllegalArgumentException.class, () -> Solution.configure(1, 0));

        Solution.configure(5, 2); // automatic threshold is 3
        check(!Solution.isClosed(), "configured sink is open");
        Solution.Command a = new Solution.Command("a", 1);
        Solution.Command b = new Solution.Command("b", 2);
        Solution.Command c = new Solution.Command("c", 5);
        eq("a", a.getText(), "text getter");
        eq(1, a.getWeight(), "weight getter");

        Solution.add(a);
        check(Solution.committed().isEmpty(), "below threshold remains buffered");
        Solution.add(b);
        eq(Arrays.asList(a, b), Solution.committed(), "threshold commits whole buffer");

        List<Solution.Command> committedSnapshot = Solution.committed();
        expect(UnsupportedOperationException.class, () -> committedSnapshot.clear());
        List<Solution.Command> emptyFlush = Solution.flush();
        check(emptyFlush.isEmpty(), "empty flush");
        expect(UnsupportedOperationException.class, () -> emptyFlush.add(a));

        List<Solution.Command> input = new ArrayList<>();
        input.add(a);
        Solution.addAll(input);
        input.clear();
        List<Solution.Command> batch = Solution.flush();
        eq(Arrays.asList(a), batch, "addAll order and defensive list handling");
        expect(UnsupportedOperationException.class, () -> batch.clear());
        eq(Arrays.asList(a, b, a), Solution.committed(), "commit order");

        Solution.add(c); // commits immediately because weight 5 >= threshold 3
        eq(Arrays.asList(a, b, a, c), Solution.committed(), "automatic heavy commit");
        expect(IllegalArgumentException.class, () -> Solution.add(null));
        expect(IllegalArgumentException.class, () -> Solution.addAll(null));
        expect(IllegalArgumentException.class, () -> Solution.addAll(Arrays.asList(a, null)));
        expect(IllegalArgumentException.class, () -> Solution.add(new Solution.Command("too-heavy", 6)));
        expect(IllegalArgumentException.class, () -> new Solution.Command(null, 1));
        expect(IllegalArgumentException.class, () -> new Solution.Command("", 1));

        Solution.add(new Solution.Command("pending", 1));
        Solution.close();
        check(Solution.isClosed(), "closed state");
        eq("pending", Solution.committed().get(4).getText(), "close flushes buffer");
        expect(IllegalStateException.class, () -> Solution.add(a));
        expect(IllegalStateException.class, () -> Solution.addAll(Arrays.asList(a)));
        expect(IllegalStateException.class, () -> Solution.flush());
        expect(IllegalStateException.class, () -> Solution.close());

        Solution.configure(2, 1);
        check(!Solution.isClosed(), "reconfiguration reopens");
        check(Solution.committed().isEmpty(), "reconfiguration clears state");
    }

    private static void check(boolean value, String message) {
        if (!value) throw new AssertionError(message);
    }
    private static void eq(Object expected, Object actual, String message) {
        if (!expected.equals(actual)) throw new AssertionError(message + ": expected=" + expected + ", actual=" + actual);
    }
    private static void expect(Class<? extends Throwable> type, Action action) {
        try { action.run(); } catch (Throwable t) {
            if (type.isInstance(t)) return;
            throw new AssertionError("Expected " + type.getName() + " but got " + t, t);
        }
        throw new AssertionError("Expected " + type.getName());
    }
    private interface Action { void run(); }
}

